<script setup>
import { onMounted, reactive, ref } from 'vue'
import { ElMessage } from 'element-plus'
import { changePassword, getProfile } from '../../api/auth'
import { getClientProfile, saveClientProfile } from '../../api/client'
import { getAgentProfile, saveAgentProfile } from '../../api/profile'
import { options, text } from '../../utils/enums'
import { messageOf } from '../../utils/request'
import { session } from '../../utils/session'
import PageHeader from '../../components/PageHeader.vue'
const role=session.user.role;const form=reactive({});const account=ref({});const saving=ref(false);const loading=ref(false);const loadError=ref('');const formRef=ref(null);const passwordOpen=ref(false);const password=reactive({oldPassword:'',newPassword:''})
const rules=Object.fromEntries(Object.entries({clientName:200,creditOrIdNo:100,industry:100,registeredAddress:500,contactAddress:500,primaryContactName:50,primaryContactPhone:20,primaryContactEmail:100,technicalPreference:500,invoiceTitle:200,taxpayerNo:100,bankName:200,bankAccount:100}).map(([key,max])=>[key,[{max,message:`最多输入 ${max} 字`,trigger:'blur'}]]))
rules.clientType=[{required:true,message:'请选择客户类型',trigger:'change'}]
rules.clientName.unshift({required:true,whitespace:true,message:'请输入客户名称',trigger:'blur'})
rules.primaryContactEmail.push({type:'email',message:'请输入有效邮箱',trigger:'blur'})
const load=async()=>{
  loading.value=true;loadError.value=''
  try{const [a,p]=await Promise.all([getProfile(),role==='CLIENT'?getClientProfile():role==='AGENT'?getAgentProfile():Promise.resolve({data:{}})]);account.value=a.data;Object.assign(form,p.data)}
  catch(e){loadError.value=messageOf(e,'资料加载失败')}finally{loading.value=false}
}
onMounted(load)
const profileFields={CLIENT:['clientType','clientName','creditOrIdNo','industry','registeredAddress','contactAddress','primaryContactName','primaryContactPhone','primaryContactEmail','technicalPreference','invoiceTitle','taxpayerNo','bankName','bankAccount'],AGENT:['licenseNo','department','practiceYears','professionalField','ipcScope','education','profile']}
const save=async()=>{
  if(saving.value||loading.value||loadError.value)return;saving.value=true
  try{
    if(role==='CLIENT'&&!await formRef.value.validate().catch(()=>false))return
    const payload=Object.fromEntries((profileFields[role]||[]).map(key=>[key,role==='CLIENT'&&typeof form[key]==='string'?form[key].trim()||null:form[key]??null]))
    if(role==='CLIENT'){await saveClientProfile(payload);Object.assign(form,(await getClientProfile()).data)}else if(role==='AGENT'){await saveAgentProfile(payload);Object.assign(form,(await getAgentProfile()).data)}
    ElMessage.success('资料已保存')
  }catch(e){ElMessage.error(messageOf(e))}finally{saving.value=false}
}
const savePassword=async()=>{try{await changePassword(password);passwordOpen.value=false;Object.assign(password,{oldPassword:'',newPassword:''});ElMessage.success('密码已修改')}catch(e){ElMessage.error(messageOf(e))}}
</script>
<template><div class="page"><PageHeader :title="role==='CLIENT'?'客户资料':'个人资料'" description="维护联系信息与业务资料"><el-button @click="passwordOpen=true">修改密码</el-button><el-button v-if="role!=='ADMIN'" type="primary" :loading="saving" :disabled="loading || !!loadError" @click="save">保存资料</el-button></PageHeader><el-alert v-if="loadError" :title="loadError" type="error" show-icon :closable="false"><el-button link @click="load">重新加载</el-button></el-alert><div v-loading="loading" class="profile-layout"><aside class="profile-aside surface"><span class="profile-avatar">{{account.realName?.slice(0,1)}}</span><h2>{{account.realName}}</h2><span>@{{account.username}}</span><el-tag>{{text('role',account.role)}}</el-tag><span>{{account.phone||'未填写电话'}}</span><span>{{account.email||'未填写邮箱'}}</span></aside><section class="profile-form-panel surface"><div class="section-title"><h2>详细资料</h2></div><el-form v-if="role==='CLIENT'" ref="formRef" :rules="rules" :disabled="loading || saving || !!loadError" class="profile-form form-grid" :model="form" label-position="top"><p v-if="!form.id && !loading && !loadError" class="span-2">请先保存客户主体资料，再管理联系人或提交案件委托。</p><h3 class="span-2">主体资料</h3><el-form-item label="客户类型" prop="clientType"><el-select v-model="form.clientType"><el-option v-for="o in options('clientType')" :key="o.value" v-bind="o"/></el-select></el-form-item><el-form-item label="客户名称" prop="clientName"><el-input v-model="form.clientName"/></el-form-item><el-form-item label="证件/信用代码" prop="creditOrIdNo"><el-input v-model="form.creditOrIdNo"/></el-form-item><el-form-item label="行业" prop="industry"><el-input v-model="form.industry"/></el-form-item><el-form-item label="注册地址" prop="registeredAddress"><el-input v-model="form.registeredAddress"/></el-form-item><h3 class="span-2">联系信息</h3><el-form-item label="通讯地址" prop="contactAddress"><el-input v-model="form.contactAddress"/></el-form-item><el-form-item label="主联系人" prop="primaryContactName"><el-input v-model="form.primaryContactName"/></el-form-item><el-form-item label="联系电话" prop="primaryContactPhone"><el-input v-model="form.primaryContactPhone"/></el-form-item><el-form-item label="联系邮箱" prop="primaryContactEmail"><el-input v-model="form.primaryContactEmail"/></el-form-item><el-form-item label="技术领域偏好" prop="technicalPreference"><el-input v-model="form.technicalPreference"/></el-form-item><h3 class="span-2">开票资料</h3><el-form-item label="发票抬头" prop="invoiceTitle"><el-input v-model="form.invoiceTitle"/></el-form-item><el-form-item label="纳税人识别号" prop="taxpayerNo"><el-input v-model="form.taxpayerNo"/></el-form-item><el-form-item label="开户行" prop="bankName"><el-input v-model="form.bankName"/></el-form-item><el-form-item label="银行账号" prop="bankAccount"><el-input v-model="form.bankAccount"/></el-form-item></el-form><el-form v-else-if="role==='AGENT'" class="profile-form form-grid" :model="form" label-position="top"><el-form-item label="工号"><el-input v-model="form.employeeNo" disabled/></el-form-item><el-form-item label="执业证号"><el-input v-model="form.licenseNo"/></el-form-item><el-form-item label="部门"><el-select v-model="form.department"><el-option v-for="v in ['PATENT','TRADEMARK','COPYRIGHT','LITIGATION','PROCESS']" :key="v" :value="v"/></el-select></el-form-item><el-form-item label="执业年限"><el-input-number v-model="form.practiceYears" :min="0"/></el-form-item><el-form-item label="专业领域"><el-input v-model="form.professionalField"/></el-form-item><el-form-item label="IPC 范围"><el-input v-model="form.ipcScope"/></el-form-item><el-form-item label="教育背景"><el-input v-model="form.education"/></el-form-item><el-form-item class="span-2" label="个人简介"><el-input v-model="form.profile" type="textarea" :rows="4"/></el-form-item></el-form><el-empty v-else description="管理员账户资料由用户管理维护"/></section></div><el-dialog v-model="passwordOpen" title="修改密码" width="min(440px,92vw)"><el-form :model="password" label-position="top"><el-form-item label="原密码"><el-input v-model="password.oldPassword" type="password" show-password/></el-form-item><el-form-item label="新密码"><el-input v-model="password.newPassword" type="password" show-password/></el-form-item></el-form><template #footer><el-button @click="passwordOpen=false">取消</el-button><el-button type="primary" @click="savePassword">确认修改</el-button></template></el-dialog></div></template>
